import os
from alpaca.common.enums import BaseURL
from alpaca.trading.client import TradingClient
from alpaca.data.historical import StockHistoricalDataClient

def make_clients(paper: bool = True):
    key, secret = os.environ.get("ALPACA_API_KEY"), os.environ.get("ALPACA_SECRET_KEY")
    if not key or not secret:
        raise RuntimeError("ALPACA_API_KEY / ALPACA_SECRET_KEY not set")
    if not paper and os.environ.get("ALPACA_LIVE_CONFIRM") != "I_UNDERSTAND_REAL_MONEY":
        raise RuntimeError("live trading gate: refusing paper=False")
    trading = TradingClient(api_key=key, secret_key=secret, paper=paper)  # -> https://paper-api.alpaca.markets
    data = StockHistoricalDataClient(api_key=key, secret_key=secret)      # -> https://data.alpaca.markets
    return trading, data

def is_paper(trading: TradingClient) -> bool:
    return trading._base_url == BaseURL.TRADING_PAPER   # secondary check: account_number.startswith("PA")

def preflight(trading):
    paper = is_paper(trading)
    try:
        acct = trading.get_account()
        clock = trading.get_clock()
    except APIError as e:
        return {"ok": False, "reason": classify(e), "paper": paper}
    an = acct.account_number or ""
    if paper and not an.startswith("PA"):
        return {"ok": False, "reason": "paper_url_but_non_PA_account", "paper": paper}
    blocked = bool(acct.trading_blocked or acct.account_blocked or acct.trade_suspended_by_user)
    ok = acct.status.value == "ACTIVE" and not blocked
    return {"ok": ok, "reason": "ok" if ok else f"account_{acct.status.value}_blocked={blocked}", "paper": paper,
            "account": an[:2] + "…" + an[-3:], "equity": float(acct.equity), "cash": float(acct.cash),
            "buying_power": float(acct.buying_power), "market_open": clock.is_open,
            "next_open": clock.next_open, "next_close": clock.next_close}

def check_tradable(trading, symbol: str, need_fractional: bool):
    a = trading.get_asset(symbol)            # APIError 404 if unknown symbol
    if a.status.value != "active" or not a.tradable:
        return False, "asset_not_tradable"
    if need_fractional and not a.fractionable:
        return False, "asset_not_fractionable"   # API rejects: 'requested asset is not fractionable'
    return True, "ok"

import hashlib
from datetime import date
from alpaca.trading.enums import OrderSide, TimeInForce
from alpaca.trading.requests import MarketOrderRequest

def make_client_order_id(run_date: date, symbol: str, side: str, tag="cp") -> str:
    base = f"{tag}-{run_date.isoformat()}-{symbol}-{side}"        # <= 128 chars required
    return base if len(base) <= 128 else base[:100] + hashlib.sha1(base.encode()).hexdigest()[:20]

def submit_notional_market(trading, symbol, side: OrderSide, notional: float, client_order_id: str):
    notional = round(float(notional), 2)
    if notional < 1.00:
        raise ValueError("Alpaca minimum notional is $1")
    try:
        return trading.get_order_by_client_id(client_order_id)   # GET /v2/orders:by_client_order_id
    except APIError as e:
        if e.status_code != 404:
            raise
    req = MarketOrderRequest(symbol=symbol, notional=notional, side=side,
                             time_in_force=TimeInForce.DAY,        # notional => market + day ONLY (else 422)
                             client_order_id=client_order_id)      # no extended_hours on market orders
    return trading.submit_order(req)

def submit_qty_market(trading, symbol, side: OrderSide, qty: float, client_order_id: str):
    qty = round(float(qty), 9)                                      # up to 9 dp; use for sells to avoid overselling
    try:
        return trading.get_order_by_client_id(client_order_id)
    except APIError as e:
        if e.status_code != 404:
            raise
    return trading.submit_order(MarketOrderRequest(symbol=symbol, qty=qty, side=side,
                                                   time_in_force=TimeInForce.DAY, client_order_id=client_order_id))
